import React, { useEffect, useState } from 'react';
import { Unity, useUnityContext } from "react-unity-webgl";

function App() {
  const [scores, setScores] = useState([]);
  const [loading, setLoading] = useState(true);

  // --- [추가] 유니티 컨텍스트 설정 ---
  // public/UnityGame/Build 폴더 안에 있는 실제 파일명과 일치하는지 꼭 확인하세요!
  const { unityProvider } = useUnityContext({
    loaderUrl: "UnityGame/Build/UnityGame.loader.js",
    dataUrl: "UnityGame/Build/UnityGame.data.br",
    frameworkUrl: "UnityGame/Build/UnityGame.framework.js.br",
    codeUrl: "UnityGame/Build/UnityGame.wasm",
  });

  // --- [기존] 점수 데이터 가져오기 로직 ---
  useEffect(() => {
    let isMounted = true;

    const fetchData = () => {
      fetch('http://localhost:5000/api/score')
        .then(res => res.json())
        .then(data => {
          if (isMounted) {
            setScores(data);
            setLoading(false);
          }
        })
        .catch(() => {
          if (isMounted) setLoading(false);
        });
    };

    fetchData(); 
    const interval = setInterval(fetchData, 3000); 

    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, []);

  // --- [추가] 기록 초기화 함수 ---
  const resetScores = async () => {
    if (window.confirm("정말로 모든 기록을 삭제하시겠습니까?")) {
      try {
        const response = await fetch('http://localhost:5000/api/score/all', {
          method: 'DELETE',
        });
        if (response.ok) {
          setScores([]); // 화면에서 즉시 데이터 비움
          alert("초기화 완료!");
        }
      } catch (error) {
        console.error("초기화 중 오류 발생:", error);
      }
    }
  };

  return (
    <div style={{ padding: 24, display: 'flex', flexDirection: 'column', alignItems: 'center', fontFamily: 'sans-serif' }}>
      <h1>🎮 부산 프로젝트 게임</h1>

      {/* --- [추가] 유니티 게임 화면 영역 --- */}
      <div style={{ 
        width: '800px', 
        height: '600px', 
        border: '5px solid #2c3e50', 
        borderRadius: '10px',
        overflow: 'hidden',
        backgroundColor: '#000',
        marginBottom: '30px'
      }}>
        <Unity unityProvider={unityProvider} style={{ width: '100%', height: '100%' }} />
      </div>

      <hr style={{ width: '100%', marginBottom: '30px' }} />

      <h2>🏆 실시간 랭킹보드</h2>

      {/* --- [추가] 기록 초기화 버튼 --- */}
      <button 
        onClick={resetScores}
        style={{
          marginBottom: '20px',
          padding: '10px 20px',
          backgroundColor: '#e74c3c',
          color: 'white',
          border: 'none',
          borderRadius: '5px',
          cursor: 'pointer',
          fontWeight: 'bold'
        }}
      >
        기록 초기화
      </button>

      {loading ? (
        <p>로딩 중...</p>
      ) : (
        <table border="1" cellPadding="8" style={{ borderCollapse: 'collapse', minWidth: '500px', textAlign: 'center', boxShadow: '0 4px 8px rgba(0,0,0,0.1)' }}>
          <thead style={{ backgroundColor: '#f8f9fa' }}>
            <tr>
              {scores.length > 0 ? (
                Object.keys(scores[0]).map((key) => (
                  <th key={key} style={{ textTransform: 'uppercase' }}>{key}</th>
                ))
              ) : (
                <th>데이터 없음</th>
              )}
            </tr>
          </thead>
          <tbody>
            {scores.length === 0 ? (
              <tr>
                <td colSpan="100%">아직 등록된 점수가 없습니다. 게임을 플레이해보세요!</td>
              </tr>
            ) : (
              // 최신 점수가 위로 오도록 정렬하거나 그대로 출력
              scores.map((score, idx) => (
                <tr key={idx}>
                  {Object.values(score).map((val, i) => (
                    <td key={i}>{val}</td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default App;
